import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type AngledCounterProps = Record<string, any>;

const AngledCounter: React.FC<AngledCounterProps> = ({
  backgroundColor = "#111111",
  textColor = "#ffffff",
  transparentBackground = false,
  targetNumber = 160,
  viewAngle = 145,
  fontSize = 300,
  durationInSeconds = 5,
}) => {
  // Load heavy condensed font "Bebas Neue" for the classic alarm clock look
  useFontLoader(["Bebas Neue"]);

  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // 1. Entrance Spring (The "Flick" motion)
  // Tuned for a mechanical "snap" feel (stiffer, slightly heavier)
  const entranceSpring = spring({
    frame,
    fps,
    config: {
      damping: 14,
      stiffness: 150,
      mass: 1.2,
    },
  });

  // 2. Static Number Display
  // Modified to display only the target number without counting up, per request.
  const currentCount = targetNumber;

  // 3. 3D Transforms
  // viewAngle input: 145 degrees.
  const wallRotation = viewAngle - 90;

  // Reduced wobble for a more rigid mechanical structure
  const rotationWobble = interpolate(entranceSpring, [0, 1], [10, 0]); 
  const currentRotation = wallRotation + rotationWobble;

  // Flick entrance: Starts flat against the "ceiling" (-90) and falls down to vertical (0)
  // This mimics a split-flap display card falling into place ("folding out of the air")
  const flickRotationX = interpolate(entranceSpring, [0, 1], [-90, 0]);
  
  // Use spring for opacity and scale to enhance the "magic" appearance
  const opacity = interpolate(entranceSpring, [0, 1], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  
  // Add scale to emphasize "folding out of the air"
  const scale = interpolate(entranceSpring, [0, 1], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  const containerStyle: React.CSSProperties = {
    backgroundColor: bgColor,
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    perspective: "1200px", // Essential for 3D effect
    overflow: "hidden",
  };

  const numberWrapperStyle: React.CSSProperties = {
    fontFamily: "Bebas Neue, sans-serif", // Changed to standard flip-clock font
    fontSize: fontSize,
    fontWeight: 400, // Bebas Neue is naturally bold
    color: textColor,
    position: "relative", // Needed for the split-line overlay
    transformStyle: "preserve-3d",
    // Combined rotation with scale for the "magic fold" effect
    transform: `rotateY(${currentRotation}deg) rotateX(${flickRotationX}deg) scale(${scale})`,
    // Hinge from the top like a falling flap
    transformOrigin: "center top",
    opacity,
    textShadow: `5px 10px 15px rgba(0,0,0,0.4)`,
    transition: "none",
    padding: "0 20px",
  };

  // Visual overlay to simulate the horizontal split of a flip clock
  const splitLineStyle: React.CSSProperties = {
    position: "absolute",
    top: "50%",
    left: 0,
    right: 0,
    height: "2px",
    backgroundColor: "rgba(0,0,0,0.2)",
    boxShadow: "0px 1px 0px rgba(255,255,255,0.1)", // Highlight for depth
    zIndex: 10,
    transform: "translateY(-50%)",
    pointerEvents: "none",
  };

  return (
    <AbsoluteFill style={containerStyle}>
      <div style={numberWrapperStyle}>
        {currentCount}
        <div style={splitLineStyle} />
      </div>
    </AbsoluteFill>
  );
};

export default AngledCounter;